import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1000, height: 700 } });
const errors = [];
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') errors.push(`${m.type()}: ${m.text()}`); });
page.on('pageerror', (e) => errors.push(`pageerror: ${e.message}`));
await page.goto('http://localhost:4173/', { waitUntil: 'networkidle' });

const info = await page.evaluate(() => ({
  h1: document.querySelector('h1')?.textContent,
  email: !!document.querySelector('#login-email[type=email]'),
  password: !!document.querySelector('#login-password[type=password]'),
  copyButtons: document.querySelectorAll('button[aria-label*="опир"], button[aria-label*="opy"]').length,
  submit: [...document.querySelectorAll('button[type=submit]')].map((b) => b.textContent),
  checkboxLabel: document.querySelector('label.g-checkbox, .g-checkbox')?.textContent,
  lang: document.querySelector('.g-root') ? 'g-root present' : 'no g-root',
  fontFamily: getComputedStyle(document.body).fontFamily,
  bodyBg: getComputedStyle(document.body).backgroundColor,
}));
console.log(JSON.stringify(info, null, 2));

const cb = page.locator('.g-checkbox input[type=checkbox]');
console.log('checkbox before:', await cb.isChecked());
await page.getByText('Запомнить меня').click();
console.log('checkbox after click:', await cb.isChecked());

await page.fill('#login-email', 'user@example.com');
await page.fill('#login-password', 'secret');
console.log('email value:', await page.inputValue('#login-email'), 'password len:', (await page.inputValue('#login-password')).length);

await page.screenshot({ path: '/tmp/pwcheck/login.png', fullPage: true });
console.log('errors:', JSON.stringify(errors, null, 2));
await browser.close();
EOF
cd /tmp/pwcheck && timeout 120 node check.mjs

